#define CUSTOM_BUF_SIZE 4096
char custom_buffer[CUSTOM_BUF_SIZE];
FILE *fp = fopen("output.dat", "w");

// 1. Fully Buffered: Use custom buffer for optimized transfers
// Buffering occurs until buffer full or explicit flush
setvbuf(fp, custom_buffer, _IOFBF, CUSTOM_BUF_SIZE);

// 2. Line Buffered: Flushes on newline or buffer full
setvbuf(stdout, NULL, _IOLBF, 0);

// 3. Unbuffered: Output/Input handled immediately
setvbuf(stderr, NULL, _IONBF, 0);

fclose(fp);
